# Generated by Claude Sonnet 4.6
# Optuna hyperparameter optimisation script wrapping train_ddpm. Each trial runs
# on a dedicated GPU using TPE (Bayesian) search over lr, channels, timesteps, and dropout.

import os
import argparse
import logging
from pathlib import Path

import torch
import optuna
from optuna.pruners import MedianPruner
from optuna.samplers import TPESampler
import lightning.pytorch as pl
from lightning.pytorch.callbacks import ModelCheckpoint, LearningRateMonitor
from lightning.pytorch.callbacks.early_stopping import EarlyStopping
from lightning.pytorch.loggers import TensorBoardLogger

from src.data_builders.dataloader import DataModule
from src.data_builders.smhi_dataloader import parse_config
from src.models import MODELREGISTRY

log = logging.getLogger(__name__)

# ── Search space ────────────────────────────────────────────────────────────────
# Adjust these ranges to taste.

SEARCH_SPACE = {
    "lr":             ("float_log", 1e-5, 1e-3),          # log-uniform
    "base_channels":  ("categorical", [16, 32, 64]),
    "dropout":        ("float", 0.0, 0.3),
    "attention":    ("categorical", [True, False]),
}

FIXED_HYPERPARAMS = {
    "target_channels": 4,
    "condition_channels": 20,
    "image_size": [432, 432],
    "backbone": "super_unet",
    "diffusion_model": "edm",
    "schedule": "cosine",
    "timesteps": 1000,
    "channel_mults": [1, 2, 4, 8],
    "attention": False,
    "num_heads": 4,
}

NUM_GPUS = torch.cuda.device_count()


# ── Optuna objective ─────────────────────────────────────────────────────────────

def objective(trial: optuna.Trial, config_path: Path, max_epochs_hpo: int) -> float:
    """One Optuna trial = one model training run on a dedicated GPU."""

    # ── Pin this trial to one GPU ──────────────────────────────────────────────
    gpu_id = trial.number % NUM_GPUS
    os.environ["CUDA_VISIBLE_DEVICES"] = str(gpu_id)

    # ── Sample hyperparameters ─────────────────────────────────────────────────
    sampled = {}
    for name, spec in SEARCH_SPACE.items():
        kind, *args = spec
        if kind == "float_log":
            sampled[name] = trial.suggest_float(name, *args, log=True)
        elif kind == "float":
            sampled[name] = trial.suggest_float(name, *args)
        elif kind == "int":
            sampled[name] = trial.suggest_int(name, *args)
        elif kind == "categorical":
            sampled[name] = trial.suggest_categorical(name, args[0])

    # ── Build hyperparameter dict (mirrors what parse_config would give) ───────
    config: dict = parse_config("training", config_path)
    hyperparameters: dict = parse_config("hyperparams", config_path)

    hyperparameters.update(sampled)
    hyperparameters.update(FIXED_HYPERPARAMS)
    hyperparameters["max_epochs"] = max_epochs_hpo
    hyperparameters["run_id"] = f"optuna_trial_{trial.number}"

    batch_size   = int(config["batch_size"])
    num_workers  = int(config["num_workers"])
    log_every_n  = int(config["log_every_n_step"])

    seed = 42 + trial.number   # Different seed per trial, but reproducible
    pl.seed_everything(seed, workers=True)

    # ── Data ──────────────────────────────────────────────────────────────────
    datamodule = DataModule(
        batch_size=batch_size,
        num_workers=num_workers,
        config_path=config_path,
        seed=seed,
    )
    datamodule.setup()

    # ── Model ─────────────────────────────────────────────────────────────────
    static_features = datamodule.train_ds.static_features
    model = MODELREGISTRY[hyperparameters["diffusion_model"]](
        backbone=hyperparameters["backbone"],
        hyperparameters=hyperparameters,
        static_features=static_features,
    )

    run_id = hyperparameters["run_id"]
    checkpoint_dir = Path(config["checkpoint_dir"]) / "optuna" / run_id

    # ── Optuna pruning callback ────────────────────────────────────────────────
    # Reports val_loss to Optuna after each epoch so bad trials can be killed early.
    pruning_callback = optuna.integration.PyTorchLightningPruningCallback(
        trial, monitor="val_loss"
    )

    trainer = pl.Trainer(
        accelerator="gpu",
        devices=1,              # One GPU per trial — parallelism is across trials
        precision="bf16-mixed",
        max_epochs=max_epochs_hpo,
        accumulate_grad_batches=4,
        callbacks=[
            ModelCheckpoint(
                dirpath=checkpoint_dir,
                filename="hpo-{epoch:03d}-{val_loss:.4f}",
                monitor="val_loss",
                mode="min",
                save_top_k=1,
            ),
            LearningRateMonitor(logging_interval="step"),
            EarlyStopping(
                monitor="val_loss",
                mode="min",
                patience=5,         # Shorter patience during HPO
                check_on_train_epoch_end=False,
            ),
            pruning_callback,
        ],
        logger=TensorBoardLogger(save_dir="logs/optuna", name=run_id),
        log_every_n_steps=log_every_n,
        enable_progress_bar=False,
    )

    trainer.fit(model, datamodule=datamodule)

    # Return best val_loss seen (not necessarily the last epoch)
    best_val_loss = trainer.callback_metrics.get("val_loss")
    if best_val_loss is None:
        raise optuna.exceptions.TrialPruned("No val_loss reported.")

    return float(best_val_loss)


# ── Main ──────────────────────────────────────────────────────────────────────

def run_hpo(config_path: str, n_trials: int, max_epochs_hpo: int, study_name: str):
    config_path = Path(config_path)
    if not config_path.exists():
        raise FileNotFoundError(f"Config not found: {config_path}")

    if NUM_GPUS == 0:
        raise RuntimeError("No GPUs found. HPO requires at least one GPU.")

    log.info(f"Running {n_trials} trials across {NUM_GPUS} GPU(s).")

    # Study is persisted to SQLite so it survives crashes and can be resumed
    storage = f"sqlite:///optuna_{study_name}.db"

    study = optuna.create_study(
        study_name=study_name,
        storage=storage,
        load_if_exists=True,        # Resume if the DB already exists
        direction="minimize",
        sampler=TPESampler(seed=42), # Bayesian (Tree-structured Parzen Estimator)
        pruner=MedianPruner(
            n_startup_trials=5,     # Don't prune the first 5 trials
            n_warmup_steps=3,       # Don't prune before epoch 3
        ),
    )

    study.optimize(
        lambda trial: objective(trial, config_path, max_epochs_hpo),
        n_trials=n_trials,
        n_jobs=NUM_GPUS,            # Run NUM_GPUS trials in parallel
        show_progress_bar=True,
    )

    # ── Results ───────────────────────────────────────────────────────────────
    print("\n" + "=" * 60)
    print(f"Best trial:  #{study.best_trial.number}")
    print(f"Best val_loss: {study.best_value:.6f}")
    print("Best hyperparameters:")
    for k, v in study.best_params.items():
        print(f"  {k}: {v}")
    print("=" * 60)

    # Save a summary
    summary_path = Path(f"optuna_{study_name}_results.txt")
    with open(summary_path, "w") as f:
        f.write(f"Best trial: #{study.best_trial.number}\n")
        f.write(f"Best val_loss: {study.best_value:.6f}\n\n")
        f.write("Best hyperparameters:\n")
        for k, v in study.best_params.items():
            f.write(f"  {k}: {v}\n")
        f.write("\nAll trials:\n")
        for t in study.trials:
            f.write(f"  Trial {t.number}: {t.value:.6f} — {t.params}\n")
    print(f"Results saved to {summary_path}")


def parse_args():
    parser = argparse.ArgumentParser(description="Optuna HPO for EDM.")
    parser.add_argument("--config_path", type=str, default="./src/configs/training_config.toml")
    parser.add_argument("--n_trials", type=int, default=20, help="Total number of HPO trials.")
    parser.add_argument("--max_epochs_hpo", type=int, default=30, help="Max epochs per trial (shorter than full training).")
    parser.add_argument("--study_name", type=str, default="edm_hpo")
    return parser.parse_args()


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    torch.set_float32_matmul_precision("medium")

    args = parse_args()
    run_hpo(
        config_path=args.config_path,
        n_trials=args.n_trials,
        max_epochs_hpo=args.max_epochs_hpo,
        study_name=args.study_name,
    )